from collections import Counter

class DetectSquares:
    def __init__(self):
        self.points = Counter()

    def add(self, point):
        self.points[tuple(point)] += 1

    def count(self, point):
        x, y = point
        total = 0
        for (px, py), diagonal_count in self.points.items():
            if px == x or abs(px - x) != abs(py - y):
                continue
            total += (
                diagonal_count
                * self.points[(x, py)]
                * self.points[(px, y)]
            )
        return total

