def maxLength(arr):
    first_index = {0: -1}
    prefix = 0
    best = 0
    for i, value in enumerate(arr):
        prefix += value
        if prefix in first_index:
            best = max(best, i - first_index[prefix])
        else:
            first_index[prefix] = i
    return best

def longestSubarray(arr, k):
    first_index = {0: -1}
    prefix = 0
    best = 0
    for i, value in enumerate(arr):
        prefix += value
        needed = prefix - k
        if needed in first_index:
            best = max(best, i - first_index[needed])
        if prefix not in first_index:
            first_index[prefix] = i
    return best

