class Solution:
    def numRescueBoats(self, people: List[int], limit: int) -> int:
        people.sort()
        ans = 0
        i, j = 0, len(people) - 1
        while i <= j:
            if people[i] + people[j] <= limit:
                i += 1
            j -= 1
            ans += 1
        return ans

def findPairsWithGivenSum(target, head):
    values = []
    current = head
    while current is not None:
        values.append(current.val)
        current = current.next

    answer = []
    left = 0
    right = len(values) - 1
    while left < right:
        total = values[left] + values[right]
        if total == target:
            answer.append([values[left], values[right]])
            left += 1
            right -= 1
        elif total < target:
            left += 1
        else:
            right -= 1
    return answer

def findUnion(a, b):
    result = []
    i = 0
    j = 0
    while i < len(a) and j < len(b):
        if a[i] < b[j]:
            value = a[i]
            i += 1
        elif b[j] < a[i]:
            value = b[j]
            j += 1
        else:
            value = a[i]
            i += 1
            j += 1
        if not result or result[-1] != value:
            result.append(value)
    while i < len(a):
        if not result or result[-1] != a[i]:
            result.append(a[i])
        i += 1
    while j < len(b):
        if not result or result[-1] != b[j]:
            result.append(b[j])
        j += 1
    return result

def intersection(arr1, arr2):
    result = []
    i = j = 0
    while i < len(arr1) and j < len(arr2):
        if arr1[i] < arr2[j]:
            i += 1
        elif arr1[i] > arr2[j]:
            j += 1
        else:
            if not result or result[-1] != arr1[i]:
                result.append(arr1[i])
            i += 1
            j += 1
    return result

