def removeLastNode(head):
    if head is None or head.next is None:
        return None
    current = head
    while current.next.next is not None:
        current = current.next
    current.next = None
    return head

def deleteKthNode(head, k):
    if head is None or k <= 0:
        return head
    if k == 1:
        return head.next
    previous = head
    for _ in range(k - 2):
        if previous.next is None:
            return head
        previous = previous.next
    if previous.next is not None:
        previous.next = previous.next.next
    return head

def deleteNodeWithValueX(head, X):
    if head is None:
        return None
    if head.val == X:
        return head.next
    current = head
    while current.next is not None:
        if current.next.val == X:
            current.next = current.next.next
            break
        current = current.next
    return head

def insertAtTail(head, X):
    new_node = ListNode(X)
    if head is None:
        return new_node
    tail = head
    while tail.next is not None:
        tail = tail.next
    tail.next = new_node
    return head

def insertBeforeX(head, X, val):
    if head is None:
        return None
    if head.val == X:
        return ListNode(val, head)

    current = head
    while current.next is not None:
        if current.next.val == X:
            current.next = ListNode(val, current.next)
            break
        current = current.next

    return head

def deleteAllOccurOfX(head, x):
    dummy = ListNode(0, head)
    previous = dummy
    current = head

    while current is not None:
        if current.val == x:
            previous.next = current.next
        else:
            previous = current
        current = current.next

    return dummy.next

