class LinkedListQueue:
    class _Node:
        def __init__(self, value):
            self.value = value
            self.next = None

    def __init__(self):
        self.head = None
        self.tail = None
        self.count = 0

    def push(self, x):
        node = self._Node(x)
        if self.tail is None:
            self.head = node
            self.tail = node
        else:
            self.tail.next = node
            self.tail = node
        self.count += 1

    def pop(self):
        if self.head is None:
            return -1
        value = self.head.value
        self.head = self.head.next
        self.count -= 1
        if self.head is None:
            self.tail = None
        return value

    def front(self):
        if self.head is None:
            return -1
        return self.head.value

    def isEmpty(self):
        return self.head is None

    def size(self):
        return self.count

