class LinkedListStack:
    class _Node:
        def __init__(self, value, next_node=None):
            self.value = value
            self.next = next_node

    def __init__(self):
        self.head = None
        self.count = 0

    def push(self, x):
        self.head = self._Node(x, self.head)
        self.count += 1

    def pop(self):
        if self.head is None:
            return -1
        value = self.head.value
        self.head = self.head.next
        self.count -= 1
        return value

    def top(self):
        if self.head is None:
            return -1
        return self.head.value

    def isEmpty(self):
        return self.head is None

    def size(self):
        return self.count

