class Solution:
    def kClosest(self, points: List[List[int]], k: int) -> List[List[int]]:
        points.sort(key=lambda p: hypot(p[0], p[1]))
        return points[:k]

def quickSort(arr, low, high):
    stack = [(low, high)]
    while stack:
        left, right = stack.pop()
        if left >= right:
            continue
        i, j = left, right
        pivot = arr[(left + right) // 2]
        while i <= j:
            while arr[i] < pivot:
                i += 1
            while arr[j] > pivot:
                j -= 1
            if i <= j:
                arr[i], arr[j] = arr[j], arr[i]
                i += 1
                j -= 1
        if left < j:
            stack.append((left, j))
        if i < right:
            stack.append((i, right))
    return arr

def inversionCount(arr):
    values = arr[:]

    def sort_count(left, right):
        if right - left <= 1:
            return 0
        mid = (left + right) // 2
        count = sort_count(left, mid) + sort_count(mid, right)
        merged = []
        i, j = left, mid
        while i < mid and j < right:
            if values[i] <= values[j]:
                merged.append(values[i])
                i += 1
            else:
                merged.append(values[j])
                count += mid - i
                j += 1
        merged.extend(values[i:mid])
        merged.extend(values[j:right])
        values[left:right] = merged
        return count

    return sort_count(0, len(values))

