from collections import defaultdict

class TimeMap:
    def __init__(self):
        self.history = defaultdict(list)

    def set(self, key: str, value: str, timestamp: int) -> None:
        self.history[key].append((timestamp, value))

    def get(self, key: str, timestamp: int) -> str:
        entries = self.history.get(key, [])
        low, high = 0, len(entries)
        while low < high:
            middle = (low + high) // 2
            if entries[middle][0] <= timestamp:
                low = middle + 1
            else:
                high = middle
        return entries[low - 1][1] if low else ""

def lowerBound(arr, target):
    low, high = 0, len(arr)
    while low < high:
        mid = low + (high - low) // 2
        if arr[mid] >= target:
            high = mid
        else:
            low = mid + 1
    return low

def upperBound(arr, target):
    low, high = 0, len(arr)
    while low < high:
        mid = low + (high - low) // 2
        if arr[mid] > target:
            high = mid
        else:
            low = mid + 1
    return low

def getFloorAndCeil(nums, x):
    lo, hi = 0, len(nums) - 1
    floor_value = -1
    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] <= x:
            floor_value = nums[mid]
            lo = mid + 1
        else:
            hi = mid - 1

    lo, hi = 0, len(nums) - 1
    ceil_value = -1
    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] >= x:
            ceil_value = nums[mid]
            hi = mid - 1
        else:
