    lo, hi = 0, n
    answer = 0
    while lo <= hi:
        mid = (lo + hi) // 2
        if mid * mid <= n:
            answer = mid
            lo = mid + 1
        else:
            hi = mid - 1
    return answer

def nthRoot(n, m):
    lo, hi = 1, m
    while lo <= hi:
        mid = (lo + hi) // 2
        value = 1
        for _ in range(n):
            value *= mid
            if value > m:
                break
        if value == m:
            return mid
        if value < m:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

