                painters += 1
                current = board
            else:
                current += board
        return painters

    lo, hi = max(arr), sum(arr)
    while lo < hi:
        mid = (lo + hi) // 2
        if painters_needed(mid) <= k:
            hi = mid
        else:
            lo = mid + 1
    return lo

def aggressiveCows(stalls, k):
    positions = sorted(stalls)

    def can_place(distance):
        count = 1
        last = positions[0]
        for position in positions[1:]:
            if position - last >= distance:
                count += 1
                last = position
                if count >= k:
                    return True
        return count >= k

    lo, hi = 0, positions[-1] - positions[0]
    answer = 0
    while lo <= hi:
        mid = (lo + hi) // 2
        if can_place(mid):
            answer = mid
            lo = mid + 1
        else:
            hi = mid - 1
    return answer

def findPages(nums, m):
    n = len(nums)
    if m < 1 or n < m:
        return -1

    def students_needed(limit):
        students = 1
        pages = 0
        for book in nums:
            if pages + book > limit:
                students += 1
                pages = book
            else:
                pages += book
        return students

    low, high = max(nums), sum(nums)
    while low < high:
        mid = (low + high) // 2
        if students_needed(mid) <= m:
            high = mid
        else:
            low = mid + 1
    return low

def kthElement(a, b, k):
    if len(a) > len(b):
        return kthElement(b, a, k)

    n, m = len(a), len(b)
    low = max(0, k - m)
    high = min(k, n)
    neg_inf = float('-inf')
    pos_inf = float('inf')

    while low <= high:
        cut_a = (low + high) // 2
        cut_b = k - cut_a
        left_a = a[cut_a - 1] if cut_a else neg_inf
        right_a = a[cut_a] if cut_a < n else pos_inf
        left_b = b[cut_b - 1] if cut_b else neg_inf
        right_b = b[cut_b] if cut_b < m else pos_inf

        if left_a <= right_b and left_b <= right_a:
            return max(left_a, left_b)
        if left_a > right_b:
            high = cut_a - 1
        else:
            low = cut_a + 1

def rowWithMax1s(mat):
    from bisect import bisect_left

    best_row = -1
    best_count = 0
    for i, row in enumerate(mat):
        count = len(row) - bisect_left(row, 1)
        if count > best_count:
            best_count = count
            best_row = i
    return best_row

def median(mat):
    from bisect import bisect_right

    low = min(row[0] for row in mat)
    high = max(row[-1] for row in mat)
    required = (len(mat) * len(mat[0])) // 2

    while low < high:
        mid = (low + high) // 2
        count = sum(bisect_right(row, mid) for row in mat)
        if count <= required:
            low = mid + 1
        else:
            high = mid
    return low

