class Solution:
    def getSum(self, a: int, b: int) -> int:
        a, b = a & 0xFFFFFFFF, b & 0xFFFFFFFF
        while b:
            carry = ((a & b) << 1) & 0xFFFFFFFF
            a, b = a ^ b, carry
        return a if a < 0x80000000 else ~(a ^ 0xFFFFFFFF)

def singleNumber(nums):
    answer = 0
    for bit in range(32):
        count = 0
        for value in nums:
            count += (value >> bit) & 1
        if count % 3:
            answer |= 1 << bit

    if answer >= 1 << 31:
        answer -= 1 << 32
    return answer

def singleNumber(nums):
    combined = 0
    for value in nums:
        combined ^= value

    distinguishing_bit = combined & -combined
    first = 0
    second = 0
    for value in nums:
        if value & distinguishing_bit:
            first ^= value
        else:
            second ^= value

    if first < second:
        return [first, second]
    return [second, first]

def findXOR(l, r):
    def prefix_xor(n):
        if n < 0:
            return 0
        remainder = n % 4
        if remainder == 0:
            return n
        if remainder == 1:
            return 1
        if remainder == 2:
            return n + 1
        return 0

    return prefix_xor(r) ^ prefix_xor(l - 1)

def missingNumber(nums):
    answer = len(nums)
    for i, value in enumerate(nums):
        answer ^= i
        answer ^= value
    return answer

