class Solution:
    def constructFromPrePost(
        self, preorder: List[int], postorder: List[int]
    ) -> Optional[TreeNode]:
        def dfs(a: int, b: int, c: int, d: int) -> Optional[TreeNode]:
            if a > b:
                return None
            root = TreeNode(preorder[a])
            if a == b:
                return root
            i = pos[preorder[a + 1]]
            m = i - c + 1
            root.left = dfs(a + 1, a + m, c, i)
            root.right = dfs(a + m + 1, b, i + 1, d - 1)
            return root

        pos = {x: i for i, x in enumerate(postorder)}
        return dfs(0, len(preorder) - 1, 0, len(postorder) - 1)

def all_traversals(root):
    preorder = []
    inorder = []
    postorder = []
    if root is None:
        return [preorder, inorder, postorder]

    stack = [(root, 1)]
    while stack:
        node, state = stack.pop()
        if state == 1:
            preorder.append(node.val)
            stack.append((node, 2))
            if node.left is not None:
                stack.append((node.left, 1))
        elif state == 2:
            inorder.append(node.val)
            stack.append((node, 3))
            if node.right is not None:
                stack.append((node.right, 1))
        else:
            postorder.append(node.val)

    return [preorder, inorder, postorder]

def isSumProperty(root):
    if root is None:
        return True
    stack = [root]
    while stack:
        node = stack.pop()
        if node.left is None and node.right is None:
            continue
        child_sum = 0
        if node.left is not None:
            child_sum += node.left.val
            stack.append(node.left)
        if node.right is not None:
            child_sum += node.right.val
            stack.append(node.right)
        if node.val != child_sum:
            return False
    return True

