def Paths(root):
    if root is None:
        return []
    answer = []
    path = []
    stack = [(root, False)]
    while stack:
        node, leaving = stack.pop()
        if leaving:
            path.pop()
            continue
        path.append(node.val)
        stack.append((node, True))
        if node.left is None and node.right is None:
            answer.append(path.copy())
        else:
            if node.right is not None:
                stack.append((node.right, False))
            if node.left is not None:
                stack.append((node.left, False))
    return answer

def lowestCommonAncestor(root, p, q):
    low = min(p.val, q.val)
    high = max(p.val, q.val)

    node = root
    while node:
        if node.val < low:
            node = node.right
        elif node.val > high:
            node = node.left
        else:
            return node

    return None

def findPreSuc(root, key):
    predecessor = -1
    successor = -1
    node = root
    while node is not None:
        if node.val < key:
            predecessor = node.val
            node = node.right
        else:
            node = node.left
    node = root
    while node is not None:
        if node.val > key:
            successor = node.val
            node = node.left
        else:
            node = node.right
    return [predecessor, successor]

