class Solution:
    def isBipartite(self, graph: List[List[int]]) -> bool:
        def dfs(a: int, c: int) -> bool:
            color[a] = c
            for b in graph[a]:
                if color[b] == c or (color[b] == 0 and not dfs(b, -c)):
                    return False
            return True

        n = len(graph)
        color = [0] * n
        for i in range(n):
            if color[i] == 0 and not dfs(i, 1):
                return False
        return True

def distanceK(root, target, k):
    from collections import deque

    if root is None:
        return []
    parent = {id(root): None}
    target_node = None
    queue = deque([root])
    while queue:
        node = queue.popleft()
        if node.val == target:
            target_node = node
        if node.left is not None:
            parent[id(node.left)] = node
            queue.append(node.left)
        if node.right is not None:
            parent[id(node.right)] = node
            queue.append(node.right)
    if target_node is None:
        return []

    queue = deque([target_node])
    seen = {id(target_node)}
    for _ in range(k):
        if not queue:
            break
        for _ in range(len(queue)):
            node = queue.popleft()
            for neighbor in (node.left, node.right, parent[id(node)]):
                if neighbor is not None and id(neighbor) not in seen:
                    seen.add(id(neighbor))
                    queue.append(neighbor)
    return [node.val for node in queue]

def minTime(root, target):
    from collections import deque

    if root is None:
        return 0
    parent = {id(root): None}
    start = None
    queue = deque([root])
    while queue:
        node = queue.popleft()
        if node.val == target:
            start = node
        if node.left is not None:
            parent[id(node.left)] = node
            queue.append(node.left)
        if node.right is not None:
            parent[id(node.right)] = node
            queue.append(node.right)
    if start is None:
        return -1

    queue = deque([(start, 0)])
    seen = {id(start)}
    answer = 0
    while queue:
        node, time = queue.popleft()
        answer = max(answer, time)
        for neighbor in (node.left, node.right, parent[id(node)]):
            if neighbor is not None and id(neighbor) not in seen:
                seen.add(id(neighbor))
                queue.append((neighbor, time + 1))
    return answer

def numProvinces(adj, V):
    seen = [False] * V
    provinces = 0

    for start in range(V):
        if seen[start]:
            continue
        provinces += 1
        seen[start] = True
        stack = [start]

        while stack:
            node = stack.pop()
            for neighbor in range(V):
                if adj[node][neighbor] and not seen[neighbor]:
                    seen[neighbor] = True
                    stack.append(neighbor)

    return provinces

