import heapq
from collections import defaultdict


class Twitter:
    def __init__(self):
        self.clock = 0
        self.tweets = defaultdict(list)
        self.following = defaultdict(set)

    def postTweet(self, userId, tweetId):
        self.clock += 1
        self.tweets[userId].append((self.clock, tweetId))

    def getNewsFeed(self, userId):
        users = set(self.following[userId])
        users.add(userId)
        heap = []

        for uid in users:
            posts = self.tweets[uid]
            if posts:
                index = len(posts) - 1
                timestamp, tweet_id = posts[index]
                heapq.heappush(heap, (-timestamp, tweet_id, uid, index))

        feed = []
        while heap and len(feed) < 10:
            _, tweet_id, uid, index = heapq.heappop(heap)
            feed.append(tweet_id)
            if index > 0:
                index -= 1
                timestamp, previous_id = self.tweets[uid][index]
                heapq.heappush(heap, (-timestamp, previous_id, uid, index))

        return feed

    def follow(self, followerId, followeeId):
        self.following[followerId].add(followeeId)

    def unfollow(self, followerId, followeeId):
        self.following[followerId].discard(followeeId)

