class minHeap:
    def __init__(self):
        self._heap = []

    def push(self, x):
        self._heap.append(x)
        i = len(self._heap) - 1
        while i > 0:
            parent = (i - 1) // 2
            if self._heap[parent] <= self._heap[i]:
                break
            self._heap[parent], self._heap[i] = self._heap[i], self._heap[parent]
            i = parent

    def pop(self):
        if not self._heap:
            return
        last = self._heap.pop()
        if not self._heap:
            return
        self._heap[0] = last
        i = 0
        n = len(self._heap)
        while True:
            smallest = i
