class maxHeap:
    def __init__(self):
        self._heap = []

    def push(self, x):
        self._heap.append(x)
        i = len(self._heap) - 1
        while i > 0:
            parent = (i - 1) // 2
            if self._heap[parent] >= self._heap[i]:
                break
            self._heap[parent], self._heap[i] = self._heap[i], self._heap[parent]
            i = parent

    def pop(self):
        if not self._heap:
            return
        last = self._heap.pop()
        if not self._heap:
            return
        self._heap[0] = last
        i = 0
        n = len(self._heap)
        while True:
            largest = i
            left = 2 * i + 1
            right = left + 1
            if left < n and self._heap[left] > self._heap[largest]:
                largest = left
            if right < n and self._heap[right] > self._heap[largest]:
                largest = right
            if largest == i:
                break
            self._heap[i], self._heap[largest] = self._heap[largest], self._heap[i]
            i = largest

    def peek(self):
        return self._heap[0] if self._heap else -1

    def size(self):
        return len(self._heap)

def heapSort(arr):
    n = len(arr)

    def sift_down(root, end):
        while True:
            child = 2 * root + 1
            if child >= end:
                return
            if child + 1 < end and arr[child + 1] > arr[child]:
                child += 1
            if arr[root] >= arr[child]:
                return
            arr[root], arr[child] = arr[child], arr[root]
            root = child

    for i in range(n // 2 - 1, -1, -1):
        sift_down(i, n)

    for end in range(n - 1, 0, -1):
        arr[0], arr[end] = arr[end], arr[0]
        sift_down(0, end)

    return arr

def kthLargestElement(nums, k):
    import heapq

    heap = []
    for value in nums:
        if len(heap) < k:
            heapq.heappush(heap, value)
        elif value > heap[0]:
            heapq.heapreplace(heap, value)
    return heap[0]

