def ratInMaze(maze):
    n = len(maze)
    if n == 0 or maze[0][0] == 0 or maze[n - 1][n - 1] == 0:
        return []

    answer = []
    visited = [[False] * n for _ in range(n)]
    moves = (('D', 1, 0), ('L', 0, -1), ('R', 0, 1), ('U', -1, 0))

    def search(row, col, path):
        if row == n - 1 and col == n - 1:
            answer.append(path)
            return
        visited[row][col] = True
        for letter, dr, dc in moves:
            nr = row + dr
            nc = col + dc
            if 0 <= nr < n and 0 <= nc < n and maze[nr][nc] == 1 and not visited[nr][nc]:
                search(nr, nc, path + letter)
        visited[row][col] = False

    search(0, 0, '')
    return answer

def graphColoring(v, edges, m):
    if v == 0:
        return True
    if m <= 0:
        return False

    adjacency = [set() for _ in range(v)]
    for first, second in edges:
        if first == second:
            return False
        adjacency[first].add(second)
        adjacency[second].add(first)

    order = sorted(range(v), key=lambda node: len(adjacency[node]), reverse=True)
    colors = [-1] * v

    def color(position):
        if position == v:
            return True
        node = order[position]
        forbidden = {colors[neighbor] for neighbor in adjacency[node] if colors[neighbor] != -1}
        for choice in range(m):
            if choice not in forbidden:
                colors[node] = choice
                if color(position + 1):
                    return True
                colors[node] = -1
        return False

    return color(0)

