    def __init__(self):
        self.root = {}

    def addWord(self, word):
        node = self.root
        for character in word:
            node = node.setdefault(character, {})
        node[None] = True

    def search(self, word):
        def matches(index, node):
            if index == len(word):
                return None in node

            character = word[index]
            if character == '.':
                for key, child in node.items():
                    if key is not None and matches(index + 1, child):
                        return True
                return False

            return character in node and matches(index + 1, node[character])

        return matches(0, self.root)

