class Solution:
    def lemonadeChange(self, bills: List[int]) -> bool:
        five = ten = 0
        for v in bills:
            if v == 5:
                five += 1
            elif v == 10:
                ten += 1
                five -= 1
            else:
                if ten:
                    ten -= 1
                    five -= 1
                else:
                    five -= 3
            if five < 0:
                return False
        return True

def fractionalKnapsack(val, wt, capacity):
    items = sorted(zip(val, wt), key=lambda item: item[0] / item[1], reverse=True)
    remaining = capacity
    total = 0.0

    for value, weight in items:
        if remaining == 0:
            break
        taken = min(weight, remaining)
        total += value * taken / weight
        remaining -= taken

    return round(total, 6)

def solve(bt):
    if not bt:
        return 0

    elapsed = 0
    total_waiting = 0
    for burst in sorted(bt):
        total_waiting += elapsed
        elapsed += burst

    return total_waiting // len(bt)

def maximumMeetings(start, end):
    meetings = sorted(zip(end, start))
    count = 0
    last_end = float('-inf')

    for meeting_end, meeting_start in meetings:
        if meeting_start > last_end:
            count += 1
            last_end = meeting_end

    return count

