def checkSubsequenceSum(nums, k):
    reachable = {0}
    for value in nums:
        additions = {total + value for total in reachable}
        reachable |= additions
        if k in reachable:
            return True
    return k in reachable

def countSubsequenceWithTargetSum(nums, k):
    counts = {0: 1}
    for value in nums:
        updated = counts.copy()
        for total, frequency in counts.items():
            new_total = total + value
            updated[new_total] = updated.get(new_total, 0) + frequency
        counts = updated
    answer = counts.get(k, 0)
    if k == 0:
        answer -= 1
    return answer

